take = clamp(d.get('take'), 1, 500, 50)
DETAIL = "SELECT TOP 1 p.*, c.Name AS CategoryName, c.Color AS CategoryColor, s.Name AS SupplierName, (SELECT b.Id AS [Id], b.Barcode AS [Barcode], b.Label AS [Label], b.PackQty AS [PackQty] FROM (SELECT TOP 2147483647 * FROM product_barcodes WHERE ProductId = p.Id ORDER BY Id) AS b FOR JSON PATH, INCLUDE_NULL_VALUES) AS BarcodesJson, (SELECT COALESCE(SUM(i.Qty), 0) FROM sale_items AS i JOIN sales AS x ON x.Id = i.SaleId WHERE i.ProductId = p.Id AND x.Status IN ('completed', 'refunded', 'partially_refunded') AND x.CompletedAt >= DATEADD(DAY, -30, SYSUTCDATETIME())) AS Sold30d FROM products AS p LEFT JOIN categories AS c ON c.Id = p.CategoryId LEFT JOIN suppliers AS s ON s.Id = p.SupplierId WHERE {where};"

def columns(src, creating):
    cols = {}
    if creating or 'name' in src:
        name = str(src.get('name') or '').strip()
        if not name:
            fail('Product name is required.')
        cols['Name'] = qs(name, 200)
    for key, col, maxlen in (('sku', 'Sku', 64), ('barcode', 'Barcode', 64), ('unit', 'Unit', 16), ('imageUrl', 'ImageUrl', 2048), ('imageFileId', 'ImageFileId', 64), ('color', 'Color', 16), ('notes', 'Notes', 2000)):
        if key in src:
            cols[col] = qs(src.get(key), maxlen, default='each' if col == 'Unit' else None)
    for key, col in (('categoryId', 'CategoryId'), ('supplierId', 'SupplierId')):
        if key in src:
            cols[col] = qi(src.get(key))
    if creating or 'priceCents' in src or 'price' in src:
        price = cents(src.get('priceCents', src.get('price')), 0 if creating else None)
        if price is not None:
            if price < 0:
                fail('Price cannot be negative.')
            cols['PriceCents'] = str(price)
    if 'costCents' in src or 'cost' in src:
        cols['CostCents'] = qi(cents(src.get('costCents', src.get('cost'))))
    if 'taxRateBp' in src:
        cols['TaxRateBp'] = qi(src.get('taxRateBp'))
    for key, col in (('taxExempt', 'TaxExempt'), ('trackInventory', 'TrackInventory'), ('isWeighed', 'IsWeighed')):
        if key in src:
            cols[col] = qb(src.get(key))
    if 'lowStockThreshold' in src:
        v = src.get('lowStockThreshold')
        cols['LowStockThreshold'] = 'NULL' if v in (None, '') else repr(float(v))
    if 'status' in src:
        st = str(src.get('status') or 'active').lower()
        if st not in ('active', 'inactive'):
            fail('Invalid status.')
        cols['Status'] = q(st)
    if creating and 'stockQty' in src:
        cols['StockQty'] = repr(qty_of(src.get('stockQty'), 0.0)) if src.get('stockQty') not in (None, '') else '0'
    return cols
if op == 'list':
    where = ['1 = 1']
    st = str(d.get('status') or '').lower()
    if st in ('active', 'inactive'):
        where.append('p.Status = ' + q(st))
    if d.get('categoryId'):
        where.append('p.CategoryId = ' + qi(d.get('categoryId')))
    if d.get('supplierId'):
        where.append('p.SupplierId = ' + qi(d.get('supplierId')))
    if d.get('lowStock'):
        where.append("p.TrackInventory = 1 AND p.StockQty <= COALESCE(p.LowStockThreshold, (SELECT CAST([Value] AS REAL) FROM settings WHERE [Key] = 'low_stock_threshold'), 5)")
    term = str(d.get('search') or '').strip()
    if term:
        where.append('(p.Name LIKE ' + like(term) + ' OR p.Sku LIKE ' + like(term) + ' OR p.Barcode LIKE ' + like(term) + ' OR EXISTS (SELECT 1 FROM product_barcodes b WHERE b.ProductId = p.Id AND b.Barcode LIKE ' + like(term) + '))')
    order = {'name': 'p.Name', 'price': 'p.PriceCents DESC', 'stock': 'p.StockQty', 'updated': 'p.UpdatedAt DESC', 'created': 'p.Id DESC'}.get(str(d.get('sort') or 'name'), 'p.Name')
    return 'SELECT p.Id, p.Name, p.Sku, p.Barcode, p.CategoryId, c.Name AS CategoryName, p.PriceCents, p.CostCents, p.StockQty, p.LowStockThreshold, p.TrackInventory, p.Unit, p.IsWeighed, p.ImageUrl, p.Status, p.UpdatedAt, COUNT_BIG(*) OVER () AS TotalCount FROM products AS p LEFT JOIN categories AS c ON c.Id = p.CategoryId WHERE ' + ' AND '.join(where) + ' ORDER BY ' + order + ' OFFSET ' + str(skip) + ' ROWS FETCH FIRST ' + str(take) + ' ROWS ONLY;'
if op == 'get':
    return DETAIL.replace('{where}', 'p.Id = ' + qi(d.get('id'), 0))
if op == 'create':
    cols = columns(d, True)
    parts = ['SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION;', 'INSERT INTO products (' + ', '.join(cols) + ') VALUES (' + ', '.join(cols.values()) + ');', 'CREATE TABLE #ctx (k nvarchar(128) PRIMARY KEY, v bigint);', 'DELETE FROM #ctx;', "INSERT INTO #ctx (k, v) VALUES ('pid', CONVERT(BIGINT, SCOPE_IDENTITY()));"]
    if 'StockQty' in cols and cols['StockQty'] not in ('0', '0.0'):
        parts.append("INSERT INTO inventory_movements (ProductId, Delta, Reason, Note, CreatedBy) VALUES ((SELECT v FROM #ctx WHERE k = 'pid'), " + cols['StockQty'] + ", 'receive', 'Opening stock', " + q(actor) + ');')
    parts += ['COMMIT TRANSACTION;', DETAIL.replace('{where}', "p.Id = (SELECT v FROM #ctx WHERE k = 'pid')"), 'DROP TABLE IF EXISTS #ctx;']
    return '\n'.join(parts)
if op == 'update':
    pid = qi(d.get('id'), 0)
    cols = columns(d, False)
    if not cols:
        return DETAIL.replace('{where}', 'p.Id = ' + pid)
    return 'UPDATE products SET ' + ', '.join((k + ' = ' + v for k, v in cols.items())) + ', UpdatedAt = SYSUTCDATETIME() WHERE Id = ' + pid + '; ' + DETAIL.replace('{where}', 'p.Id = ' + pid)
